    "crystal":   { "hp": 1, "loot": { "crystal": [1, 2] } },
    "gem":       { "hp": 2, "loot": { "gem": [1, 1] } },
    "geode":     { "hp": 1, "loot": { "geode": [1, 1] } },
    "fossil":    { "hp": 1, "loot": {} },
    "chest":     { "hp": 0, "loot": {} },
