    "tank":  { "name": "Energy tank",   "emoji": "🔋", "blurb": "+12 most energy",                                 "max": 10, "cost": 50,  "growth": 1.9 },
    "regen": { "name": "Miner’s lungs", "emoji": "💨", "blurb": "Energy comes back faster",                         "max": 10, "cost": 80,  "growth": 1.9 },
